    var dest = arg_dest;
    _ = &dest;
    var src = arg_src;
    _ = &src;
    dest.*.type = src.*.type;
    if (@as(c_uint, @bitCast(@as(c_int, @as(c_int, src.*.type)))) == ESP_IPADDR_TYPE_V6) {
        dest.*.u_addr.ip6.addr[@as(c_int, 0)] = src.*.u_addr.ip6.addr[@as(c_int, 0)];
        dest.*.u_addr.ip6.addr[@as(c_int, 1)] = src.*.u_addr.ip6.addr[@as(c_int, 1)];
        dest.*.u_addr.ip6.addr[@as(c_int, 2)] = src.*.u_addr.ip6.addr[@as(c_int, 2)];
        dest.*.u_addr.ip6.addr[@as(c_int, 3)] = src.*.u_addr.ip6.addr[@as(c_int, 3)];
        dest.*.u_addr.ip6.zone = src.*.u_addr.ip6.zone;
    } else {
        dest.*.u_addr.ip4.addr = src.*.u_addr.ip4.addr;
        dest.*.u_addr.ip6.addr[@as(c_int, 1)] = 0;
        dest.*.u_addr.ip6.addr[@as(c_int, 2)] = 0;
        dest.*.u_addr.ip6.addr[@as(c_int, 3)] = 0;
        dest.*.u_addr.ip6.zone = 0;
    }
}
